CREATE POLICY phase_a_area_grant ON public.finance_holder_reimbursements FOR SELECT TO authenticated USING(project_expense_id IS NOT NULL AND public.pm_project_access_cutover_active() AND public.pm_phase_a_expense_read(project_expense_id));
CREATE FUNCTION public.pm_phase_a_batch_grant(_batch uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.pm_project_access_cutover_active() AND EXISTS(SELECT 1 FROM public.project_reimbursement_allocations a JOIN public.finance_holder_reimbursements o ON o.id=a.obligation_id WHERE a.batch_id=_batch AND o.project_expense_id IS NOT NULL) AND public.pm_phase_a_batch_gate(_batch) $$;
REVOKE ALL ON FUNCTION public.pm_phase_a_batch_grant(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_phase_a_batch_grant(uuid) TO authenticated,service_role;
CREATE POLICY phase_a_area_grant ON public.project_reimbursement_batches FOR SELECT TO authenticated USING(public.pm_phase_a_batch_grant(id));
CREATE POLICY phase_a_expense_financial_gate ON public.project_expense_invoice_allocations AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT public.pm_project_access_cutover_active() OR EXISTS(SELECT 1 FROM public.financial_document_lines l WHERE l.id=project_expense_invoice_allocations.line_id));
CREATE POLICY phase_a_area_grant ON public.financial_documents FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND (project_id IS NOT NULL OR project_expense_id IS NOT NULL) AND public.pm_phase_a_queue_gate(project_id,project_expense_id,direction::text));
CREATE POLICY phase_a_area_grant ON public.financial_document_lines FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND EXISTS(SELECT 1 FROM public.financial_documents d WHERE d.id=financial_document_lines.document_id AND (d.project_id IS NOT NULL OR d.project_expense_id IS NOT NULL)));
CREATE POLICY phase_a_area_grant ON public.financial_document_review_queue FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND (created_project_id IS NOT NULL OR source_project_expense_id IS NOT NULL) AND public.pm_phase_a_queue_gate(created_project_id,source_project_expense_id,direction::text));
CREATE POLICY phase_a_area_grant ON public.pm_invoice_settings FOR SELECT TO authenticated USING(project_id IS NOT NULL AND public.pm_phase_a_area_grant(project_id,'financials'));
CREATE POLICY phase_a_project_settings_gate ON public.pm_invoice_settings AS RESTRICTIVE FOR SELECT TO authenticated USING(project_id IS NULL OR public.pm_phase_a_area_gate(project_id,'financials'));
COMMENT ON FUNCTION public.pm_phase_a_batch_grant(uuid) IS 'Gated definer batch capability prevents parent-child RLS recursion; every included project still requires Expenses.';